  else if (style === 'blue') { warmH = 210; coolH = 260; }
  else if (style === 'infrared') { warmH = 20; coolH = 340; }
  else if (style === 'ink') { warmH = 30; coolH = 30; }
  const HSBtoRGB = (h, s, v, out) => { h = hw(h) / 60; const c = v * s, x = c * (1 - Math.abs((h % 2) - 1)), m = v - c; let r, g, b;
    if (h < 1) { r = c; g = x; b = 0; } else if (h < 2) { r = x; g = c; b = 0; } else if (h < 3) { r = 0; g = c; b = x; }
    else if (h < 4) { r = 0; g = x; b = c; } else if (h < 5) { r = x; g = 0; b = c; } else { r = c; g = 0; b = x; }
    out[0] = (r + m) * 255; out[1] = (g + m) * 255; out[2] = (b + m) * 255; };
  const cc = [0, 0, 0];
  for (let j = 0; j < BH; j++) {
    const fy = j / BH;
    for (let i = 0; i < BW; i++) {
      const fx = i / BW;
