  HSBtoRGB(rimH, style === 'ink' ? 0.1 : 0.7, 1, cc);
  for (let j = 0; j < BH; j++) {
    const fy = j / BH;
    for (let i = 0; i < BW; i++) {
      const fx = i / BW;
      let rim = 0;
      for (let k = 0; k < NP; k++) {
        if (fy < ptop[k]) continue;
        const wob = (fbm(fy * 5 + pph[k], k * 3.3, sd * 7 + k) - 0.5) * 0.10;
        const cxk = pcx[k] + wob;
